<?php require __DIR__.'/../config/config.php';require __DIR__.'/../includes/functions.php';$errors=[];$data=['id_anggota'=>'','id_buku'=>'','tgl_pinjam'=>date('Y-m-d')];if($_SERVER['REQUEST_METHOD']==='POST'){$data=array_map('trim',array_merge($data,$_POST));if(!$data['id_anggota']||!$data['id_buku'])$errors[]='Anggota dan buku wajib dipilih.';if(!$errors){try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT stok FROM buku WHERE id_buku=? FOR UPDATE');$s->execute([$data['id_buku']]);$stok=$s->fetchColumn();if($stok===false||(int)$stok<1)throw new RuntimeException('Stok buku habis atau buku tidak ditemukan.');$s=$pdo->prepare("INSERT INTO peminjaman(id_anggota,id_buku,tgl_pinjam,status) VALUES(?,?,?,'dipinjam')");$s->execute([$data['id_anggota'],$data['id_buku'],$data['tgl_pinjam']]);$pdo->prepare('UPDATE buku SET stok=stok-1 WHERE id_buku=?')->execute([$data['id_buku']]);$pdo->commit();flash('success','Peminjaman berhasil dicatat.');redirect('index.php');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Data anggota/buku tidak valid atau terjadi kesalahan database.';}catch(RuntimeException $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage();}}}$members=$pdo->query('SELECT id_anggota,nama FROM anggota ORDER BY id_anggota')->fetchAll();$books=$pdo->query('SELECT id_buku,judul,stok FROM buku WHERE stok>0 ORDER BY judul')->fetchAll();$title='Pinjam Buku';require __DIR__.'/../includes/header.php';?><h3>Pinjam Buku</h3><?php if($errors):?><div class="alert alert-danger"><ul><?php foreach($errors as $er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="card card-body"><div class="mb-3"><label class="form-label">Anggota</label><select name="id_anggota" class="form-select" required><option value="">-- pilih anggota --</option><?php foreach($members as $m):?><option value="<?=e($m['id_anggota'])?>" <?=$data['id_anggota']===$m['id_anggota']?'selected':''?>><?=e($m['id_anggota'].' - '.$m['nama'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Buku (stok tersedia)</label><select name="id_buku" class="form-select" required><option value="">-- pilih buku --</option><?php foreach($books as $b):?><option value="<?=e($b['id_buku'])?>" <?=$data['id_buku']===$b['id_buku']?'selected':''?>><?=e($b['judul'].' (stok '.$b['stok'].')')?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Tanggal Pinjam</label><input type="date" name="tgl_pinjam" class="form-control" value="<?=e($data['tgl_pinjam'])?>" required></div><button class="btn btn-primary">Simpan Peminjaman</button> <a href="index.php" class="btn btn-secondary">Batal</a></form><?php require __DIR__.'/../includes/footer.php';?>
